const action = String(msg.payload || '').toUpperCase();
let state = context.get('state') || {
    loading_state: 'AGUARDANDO',
    planned: 120,
    loaded: 0,
    wrong: 0,
    no_read: 0,
    returns: 0,
    last_event: 'RESET',
    emergency: false
};
let event = null;
const operational = ['CARREGANDO', 'PAUSADO'];

if (action === 'RESET') {
    state = { loading_state: 'AGUARDANDO', planned: 120, loaded: 0, wrong: 0, no_read: 0, returns: 0, last_event: 'RESET', emergency: false };
} else if (action === 'INICIAR' && !state.emergency) {
    state.loading_state = 'CARREGANDO';
    state.last_event = 'CARREGAMENTO_INICIADO';
} else if (action === 'PAUSAR' && state.loading_state === 'CARREGANDO') {
    state.loading_state = 'PAUSADO';
    state.last_event = 'CARREGAMENTO_PAUSADO';
} else if (action === 'EMERGENCIA') {
    state.emergency = true;
    state.loading_state = 'EMERGENCIA';
    state.last_event = 'EMERGENCIA_ATIVADA';
} else if (action === 'RETORNO' && state.loading_state === 'PAUSADO' && state.loaded > 0) {
    state.loaded -= 1;
    state.returns += 1;
    state.last_event = 'RETORNO_REGISTRADO';
    event = 'RETORNO';
} else if (action === 'LEITURA_CORRETA' && state.loading_state === 'CARREGANDO' && !state.emergency) {
    if (state.loaded < state.planned) {
        state.loaded += 1;
        state.last_event = 'LEITURA_VALIDA';
        event = 'VALIDO';
        if (state.loaded === state.planned) state.loading_state = 'FINALIZANDO';
    } else {
        state.last_event = 'EXCESSO';
        event = 'EXCESSO';
    }
} else if (action === 'LEITURA_INCORRETA' && operational.includes(state.loading_state)) {
    state.wrong += 1;
    state.loading_state = 'PAUSADO';
    state.last_event = 'PRODUTO_INCORRETO';
    event = 'PRODUTO_INCORRETO';
} else if (action === 'SEM_LEITURA' && operational.includes(state.loading_state)) {
    state.no_read += 1;
    state.loading_state = 'PAUSADO';
    state.last_event = 'SEM_LEITURA';
    event = 'SEM_LEITURA';
} else {
    state.last_event = `IGNORADO_${action}`;
}

context.set('state', state);
const result = {
    source: 'trace-clp-simulador',
    event,
    state: { ...state },
    progress: state.planned ? Math.round((state.loaded / state.planned) * 100) : 0,
    safe: true
};
const eventMsg = event ? { topic: 'trace/evento', payload: result } : null;
const stateMsg = { topic: 'trace/estado', payload: result };
return [eventMsg, stateMsg];
